{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO/JCO relocation assistance amounts, July 2026 to June 2027","requirement":"An owner who displaces an eligible or qualified tenant from an RSO or JCO rental unit must pay the standardized relocation amount for that household type and length of tenancy.","key_value":"Eligible tenant: $11,000 (under 3 years) / $14,400 (3+ years or low income); qualified tenant: $23,150 / $27,400","coverage_conditions":"Tenants displaced from rental units covered by the Rent Stabilization Ordinance or the Just Cause Ordinance in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"RSO or JCO covered rental units; displaced tenant"},"exemptions":null,"penalty":null,"effective_date":"2026-07-01","citation":"Relocation Assistance Bulletin (Rev. 07.01.2026), Chart A","quoted_span":"CHART A: RSO or JCO Amounts
