{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Relocation for demolition and new construction limited to lower income households","requirement":"Where units are demolished for new construction, only lower income households displaced must receive relocation payments equal to the benefits public entities must pay under Government Code Chapter 16. Other tenants get at least the RSO or JCO amounts.","key_value":"Minimum RSO/JCO amounts; increased only if the HCA or RPO requires","coverage_conditions":"Households displaced by demolition of their units where the owner will replace them with new construction; the mandatory payment attaches to lower income households.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Displacement for demolition and new construction; household income"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Gov. Code § 66300.6(b)(4)(A)","quoted_span":"The City’s Resident Protections Ordinance (RPO) and the State’s Housing Crisis Act (HCA) require that ONLY lower income households being displaced for the purpose of demolition of their units where the owner will replace the units with new construction must receive relocation payment","interaction":"The City’s Resident Protections Ordinance also applies these relocation requirements.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RPO standardized relocation payments for lower income households displaced by new development","requirement":"An owner displacing a low, very low or extremely low income household for new development must pay the standardized relocation amount shown for that income tier.","key_value":"$115,480 extremely low income; $96,750 very low income; $87,450 low income","coverage_conditions":"Only low, very low and extremely low income households displaced by new development.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Displacement by new development; household income at or below 80% AMI"},"exemptions":"Households above low income are paid RSO or JCO amounts under Chart A instead.","penalty":null,"effective_date":"2026-07-01","citation":"Relocation Assistance Bulletin (Rev. 07.01.2026), Chart B","quoted_span":"CHART B: Resident Protections Ordinance Standardized Payments
