{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Single-family dwelling relocation payment by natural-person owner","requirement":"An owner who is a natural person and owns no more than four dwelling units plus one single-family home on a separate lot must pay one month's rent in effect when the termination notice was served, as payment or credit.","key_value":"1 month's rent","coverage_conditions":"Single-family dwelling subject to the JCO owned by a natural person, including through a trust or registered legal entity controlled by that person, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":4,"owner_dependent":true,"other":"Single-family dwelling subject to the JCO; natural-person owner"},"exemptions":"Los Angeles Municipal Code Section 151.30(E) does not apply.","penalty":null,"effective_date":null,"citation":"L.A. Mun. Code § 165.06","quoted_span":"who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles: one month’s rent that was in effect when the landlord served the written notice to terminate the tenancy, as either a monetary payment or credit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Relocation payment deadline, pro rata shares and escrow option","requirement":"Relocation payments must be made available within 15 days of service of the written notice of eviction; the landlord may instead place the money in an escrow account within that same 15-day period.","key_value":"15 days","coverage_conditions":"Relocation assistance payments required by the City's RSO and JCO ordinances.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":"A tenant may raise the landlord's failure to provide relocation assistance as an affirmative defense in an action to recover possession and may file a complaint with LAHD.","effective_date":null,"citation":"RAC Regulations § 960.00","quoted_span":"Payments shall be made available within fifteen (15) days of service of the written notice of eviction; however, the landlord may, at the landlord's sole discretion and at the landlord's cost, elect to pay the monetary relocation benefits through an escrow account.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-02","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Relocation offset against accumulated rent","requirement":"A landlord may offset a tenant's accumulated rent against relocation assistance, except where the assistance is owed because a governmental order requires the tenant to vacate or comply for an unpermitted dwelling.","key_value":null,"coverage_conditions":"Relocation assistance owed to tenants under the City's RSO and JCO ordinances.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Offset is not allowed where the relocation assistance is owed because of a governmental agency order to vacate or comply issued for an unpermitted dwelling.","penalty":null,"effective_date":null,"citation":"L.A. Mun. Code § 151.09","quoted_span":"Relocation Offset: A landlord may offset the tenant's accumulated rent against any relocation assistance, unless the relocation assistance is owed because a termination of tenancy is required by a governmental agency order to vacate or comply issued for an unpermitted dwelling.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
